  static ToolStripButton Add(ToolStrip strip,string text,Action action){var b=new ToolStripButton(text){DisplayStyle=ToolStripItemDisplayStyle.Text};b.Click+=(s,e)=>action();strip.Items.Add(b);return b;}

  static void Grid(DataGridView grid,string[] names){grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.BackgroundColor=Color.White;grid.BorderStyle=BorderStyle.None;grid.AlternatingRowsDefaultCellStyle.BackColor=Color.FromArgb(244,248,252);grid.DefaultCellStyle.Font=new Font("Segoe UI",9);grid.ColumnHeadersDefaultCellStyle.Font=new Font("Segoe UI",9);grid.ColumnHeadersHeight=48;grid.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.DisableResizing;foreach(string n in names)grid.Columns.Add(n,n);grid.Columns[0].FillWeight=145;}

  sealed class ShaftItem {public string Id,Name;public override string ToString(){return Name;}}

  sealed class LinkItem {public string Id,Name;public override string ToString(){return Name;}}

  MechanismPart Selected{get{return Project.Find(selectedId);}}

  internal void SetProject(MechanismProject p){Project=p;selectedId=null;undo.Clear();redo.Clear();Rebuild();}

  void Rebuild(){Stop();Assembly=MechanismCad.Build(Project);Solution=MechanismSolver.Solve(Project);updating=true;try{tree.BeginUpdate();tree.Nodes.Clear();drive.Items.Clear();foreach(var s in Project.Parts.Where(p=>p.Kind=="shaft")){drive.Items.Add(new ShaftItem{Id=s.Id,Name=s.Name});var root=new TreeNode(s.Name){Tag=s.Id};foreach(var part in Project.Parts.Where(p=>p.ShaftId==s.Id))root.Nodes.Add(new TreeNode(part.Name){Tag=part.Id});tree.Nodes.Add(root);root.Expand();}foreach(var p in Project.Parts.Where(p=>p.Kind!="shaft"&&string.IsNullOrEmpty(p.ShaftId)))tree.Nodes.Add(new TreeNode(p.Name+" · свободная"){Tag=p.Id});foreach(ShaftItem s in drive.Items)if(s.Id==Project.DriveShaftId){drive.SelectedItem=s;break;}rpm.Commit((decimal)Project.InputRpm);torque.Commit((decimal)Project.InputTorque);tree.EndUpdate();}finally{updating=false;}empty.Visible=Project.Parts.Count==0;if(!empty.Visible){var result=MechanismCad.ViewResult(Project,Solution,Assembly);Scene.SetResult(result,true);}else Scene.SetResult(null,false);connections.Items.Clear();foreach(var l in Project.Links){var a=Project.Find(l.FromId);var b=Project.Find(l.ToId);connections.Items.Add(new LinkItem{Id=l.Id,Name=(a==null?"?":a.Name)+" → "+(b==null?"?":b.Name)+" · "+(l.Kind=="gear"?"зацепление":l.Kind=="belt"?"ремень":"муфта")+" · η="+Engine.F(l.Efficiency)});}UpdateResults();SelectPart(selectedId);lastSerialized=Project.Serialize();undoButton.Enabled=undo.Count>0;redoButton.Enabled=redo.Count>0;Text="GearLab 3 · "+(currentFile==null?Project.Name:Path.GetFileName(currentFile))+(lastSerialized!=savedSerialized?" *":"");}

  void UpdateResults(){shafts.Rows.Clear();meshes.Rows.Clear();foreach(var s in Project.Parts.Where(p=>p.Kind=="shaft")){MechanismShaftState st;if(!Solution.Shafts.TryGetValue(s.Id,out st))continue;bool known=Solution.Valid&&st.Connected;shafts.Rows.Add(s.Name,known?Engine.F(st.Rpm):"—",known?Engine.F(st.AvailableTorque):"—",known?Engine.F(st.RequiredTorque):"—",known?Engine.F(st.LoadPower):"—",known?(Solution.Overloaded?"Обороты не обеспечены":"Связан с входом"):"Нет расчёта / связи");}foreach(var e in Solution.Meshes){var a=Project.Find(e.DriverId);var b=Project.Find(e.DrivenId);meshes.Rows.Add(a.Name+" → "+b.Name,Engine.F(e.Ratio),Engine.F(e.Efficiency),Engine.F(e.Torque),Engine.F(e.TangentialForce),Engine.F(e.RadialForce),Engine.F(e.AxialForce),Engine.F(e.CapacityForce));}var errors=Assembly.Errors.Concat(Solution.Errors).Distinct().ToList();if(errors.Count>0){summary.ForeColor=Color.Firebrick;summary.Text=string.Join("   ",errors.Take(2));}else if(Project.Parts.Count==0){summary.ForeColor=Color.FromArgb(36,76,116);summary.Text="Пустой проект. Добавьте вал, задайте ему обороты и момент; затем создавайте и соединяйте детали.";}else{summary.ForeColor=Solution.Overloaded?Color.Firebrick:Color.FromArgb(29,111,81);summary.Text="Вход: "+Engine.F(Project.InputRpm)+" об/мин · "+Engine.F(Project.InputTorque)+" Н·м · "+Engine.F(Solution.InputPower)+" Вт     Требуется на входе: "+Engine.F(Solution.RequiredTorque)+" Н·м"+(Solution.Overloaded?"   МОМЕНТА НЕДОСТАТОЧНО":"   Запас: "+Engine.F(Project.InputTorque-Solution.RequiredTorque)+" Н·м");}explanation.Text=string.Join(Environment.NewLine+Environment.NewLine,errors.Concat(Solution.Notes))+Environment.NewLine+Environment.NewLine+"* Обороты по кинематическим связям при удержании заданной скорости входа. Предельный момент — преобразованный входной момент одной ветви, не допустимая прочность детали. Ft/Fr нагрузки рассчитываются из заданных сопротивляющих моментов. Без заданной нагрузки они равны нулю.";status.Text=Project.Parts.Count+" деталей · "+Project.Links.Count+" связей · "+(errors.Count>0?"Исправьте ошибки":"Размеры и положение сохраняются в проекте; STEP — твёрдые тела");play.Enabled=Project.Parts.Count>0&&Assembly.Valid&&Solution.Valid&&!Solution.Overloaded&&Project.InputRpm!=0;}

  internal void SelectPart(string id){selectedId=Project.Find(id)==null?null:id;updating=true;try{var p=Selected;properties.SelectedObject=p==null?null:new MechanismProperties(p);mount.Items.Clear();mount.Items.Add(new ShaftItem{Id=null,Name="Не установлена на вал"});foreach(var s in Project.Parts.Where(a=>a.Kind=="shaft"))mount.Items.Add(new ShaftItem{Id=s.Id,Name=s.Name});mount.Enabled=p!=null&&p.Kind!="shaft";if(p!=null){foreach(ShaftItem choice in mount.Items)if(choice.Id==p.ShaftId){mount.SelectedItem=choice;break;}var pos=Project.Position(p);double mass=Assembly.Parts.Where(a=>a.Id==p.Id).Sum(a=>a.Volume())*1e-9*p.Density;selectedInfo.Text=p.Name+" · масса "+Engine.F(mass)+" кг\nXYZ: "+string.Join("; ",pos.Select(Engine.F))+" мм";foreach(TreeNode root in tree.Nodes){if((string)root.Tag==id)tree.SelectedNode=root;foreach(TreeNode n in root.Nodes)if((string)n.Tag==id)tree.SelectedNode=n;}}else selectedInfo.Text="Выберите деталь в дереве или в 3D.";exportPart.Enabled=p!=null;Scene.Select(selectedId);}finally{updating=false;}}

  bool Mutate(Action action){string before=Project.Serialize();try{action();var errors=MechanismCad.Validate(Project);if(errors.Count>0)throw new Exception(string.Join("\n",errors.Take(5)));PushUndo(before);Rebuild();return true;}catch(Exception ex){Project=MechanismProject.Parse(before);Rebuild();UiMessage.Show(this,ex.Message,"Изменение не применено",MessageBoxButtons.OK,MessageBoxIcon.Information);return false;}}

  void PushUndo(string before){if(before==Project.Serialize())return;undo.Push(before);redo.Clear();if(undo.Count>60){var keep=undo.Take(60).Reverse().ToArray();undo.Clear();foreach(string item in keep)undo.Push(item);}}

  void CommitProperty(){if(updating)return;var before=lastSerialized;var errors=MechanismCad.Validate(Project);if(errors.Count>0){Project=MechanismProject.Parse(before);Rebuild();UiMessage.Show(this,string.Join("\n",errors.Take(5)),"Размеры не применены");return;}PushUndo(before);Rebuild();}

  internal bool AddPart(string kind){if(kind=="sketch"){using(var dialog=new MechanismSketchDialog(new MechanismPoint[0])){if(dialog.ShowLocalizedDialog(this)!=DialogResult.OK)return false;return Mutate(()=>{var p=Project.Add(kind);p.Outline=dialog.Points;selectedId=p.Id;});}}return Mutate(()=>{var shaft=Project.Shaft(Selected);var p=Project.Add(kind);selectedId=p.Id;if(kind=="shaft"){p.X=Project.Parts.Count(a=>a.Kind=="shaft")*60-60;}else if(shaft!=null&&(kind=="gear"||kind=="pulley"||kind=="bearing")){p.ShaftId=shaft.Id;p.OffsetZ=Math.Min(10,Math.Max(0,Project.ShaftLength(shaft)-p.Length));}else{p.X=20;p.Y=20;}});}

  void DeletePart(){if(Selected!=null){string id=selectedId;Mutate(()=>{Project.Remove(id);selectedId=null;});}}

  void Connect(){EditConnection(null);}void EditConnection(MechanismLink edit){using(var d=new MechanismLinkDialog(Project,selectedId)){if(edit!=null){d.Type.SelectedIndex=edit.Kind=="gear"?0:edit.Kind=="belt"?1:2;d.From.SelectedItem=Project.Find(edit.FromId);d.To.SelectedItem=Project.Find(edit.ToId);d.Efficiency.Value=(decimal)(MechanismCad.Finite(edit.Efficiency)?Math.Max(.001,Math.Min(1,edit.Efficiency)):.97);d.Angle.Value=(decimal)(MechanismCad.Finite(edit.PlacementAngle)?Math.Max(-360,Math.Min(360,edit.PlacementAngle)):0);d.Arrange.Checked=false;}if(d.ShowLocalizedDialog(this)!=DialogResult.OK)return;var link=d.Create();Mutate(()=>{if(edit!=null){Project.Links.RemoveAll(l=>l.Id==edit.Id);link.Id=edit.Id;}Project.Links.Add(link);if(d.Arrange.Checked)MechanismCad.ArrangeLink(Project,link);var errors=MechanismSolver.Solve(Project).Errors;if(errors.Count>0)throw new Exception(string.Join("\n",errors.Take(5)));});}}

  void Holes(){if(NativeOnly())return;var p=Selected;if(p==null)return;var copy=p.Holes.Select(h=>new MechanismHole{Name=h.Name,X=h.X,Y=h.Y,Diameter=h.Diameter,Depth=h.Depth}).ToList();var source=new BindingSource{DataSource=new BindingList<MechanismHole>(copy)};using(var d=new MechanismTableDialog("Отверстия / круглые карманы: "+p.Name,source))if(d.ShowLocalizedDialog(this)==DialogResult.OK)Mutate(()=>p.Holes=copy);}

  void Steps(){if(NativeOnly())return;var p=Selected;if(p==null||p.Kind!="shaft"){UiMessage.Show(this,"Выберите вал.");return;}var copy=p.Steps.Select(s=>new MechanismStep{Length=s.Length,Diameter=s.Diameter,Bore=s.Bore}).ToList();if(copy.Count==0)copy.Add(new MechanismStep{Length=p.Length,Diameter=p.Diameter,Bore=p.Bore});var source=new BindingSource{DataSource=new BindingList<MechanismStep>(copy)};using(var d=new MechanismTableDialog("Ступени вдоль +Z: "+p.Name,source))if(d.ShowLocalizedDialog(this)==DialogResult.OK)Mutate(()=>p.Steps=copy);}

  void EditSketch(){if(NativeOnly())return;var p=Selected;if(p==null||p.Kind!="sketch"){UiMessage.Show(this,"Выберите выдавленный эскиз или создайте новый через «Создать деталь».");return;}using(var d=new MechanismSketchDialog(p.Outline))if(d.ShowLocalizedDialog(this)==DialogResult.OK)Mutate(()=>p.Outline=d.Points);}

  void CommitDrag(string id,Vector3D delta){var p=Project.Find(id);if(p==null)return;Stop();if(!string.IsNullOrEmpty(p.ShaftId)&&(Math.Abs(delta.X)>.001||Math.Abs(delta.Y)>.001)){Rebuild();status.Text="Деталь закреплена на валу: перемещайте вал целиком или выберите ось Z для сдвига детали по валу.";return;}Mutate(()=>{if(string.IsNullOrEmpty(p.ShaftId)){p.X=AppSettings.Snap(p.X+delta.X);p.Y=AppSettings.Snap(p.Y+delta.Y);p.Z=AppSettings.Snap(p.Z+delta.Z);}else p.OffsetZ=AppSettings.Snap(p.OffsetZ+delta.Z);});}

  void Undo(){if(undo.Count==0)return;redo.Push(Project.Serialize());Project=MechanismProject.Parse(undo.Pop());Rebuild();}

  void Redo(){if(redo.Count==0)return;undo.Push(Project.Serialize());Project=MechanismProject.Parse(redo.Pop());Rebuild();}

  void Replace(MechanismProject p,string file){if(!Confirm())return;Project=p;currentFile=file;selectedId=null;undo.Clear();redo.Clear();savedSerialized=p.Serialize();Rebuild();}

  void Open(){if(!Confirm())return;using(var d=new OpenFileDialog{Filter="Механизм GearLab|*.mechanism.json|JSON|*.json"})if(d.ShowLocalizedDialog(this)==DialogResult.OK)try{var p=MechanismProject.Parse(File.ReadAllText(d.FileName));Project=p;currentFile=d.FileName;selectedId=null;undo.Clear();redo.Clear();savedSerialized=p.Serialize();Rebuild();}catch(Exception ex){UiMessage.Show(this,ex.Message,"Файл не открыт");}}

  bool Save(bool choose){try{string file=currentFile;if(choose||file==null)using(var d=new SaveFileDialog{Filter="Механизм GearLab|*.mechanism.json",FileName="Мой_механизм.mechanism.json",DefaultExt="mechanism.json",OverwritePrompt=true}){if(d.ShowLocalizedDialog(this)!=DialogResult.OK)return false;file=d.FileName;}Project.Save(file);currentFile=file;savedSerialized=Project.Serialize();lastSerialized=savedSerialized;Text="GearLab 3 · "+Path.GetFileName(file);status.Text="Проект сохранён: "+file;return true;}catch(Exception ex){UiMessage.Show(this,ex.Message,"Сохранение");return false;}}

  bool Confirm(){if(Project.Serialize()==savedSerialized)return true;var answer=UiMessage.Show(this,"Сохранить изменения механизма?","Проект",MessageBoxButtons.YesNoCancel,MessageBoxIcon.Question);return answer==DialogResult.No||(answer==DialogResult.Yes&&Save(false));}

  CadAssembly ExportModel(bool one){var model=MechanismCad.Build(Project);if(!model.Valid)throw new Exception("Сначала создайте допустимые тела: "+string.Join("; ",model.Errors));if(one){if(Selected==null)throw new Exception("Выберите деталь.");model.Parts.RemoveAll(p=>p.Id!=selectedId);}return model;}

  void ExportStep(bool one){try{var model=ExportModel(one);using(var d=new SaveFileDialog{Filter="STEP — твёрдые тела|*.step",FileName=one?"Деталь.step":"Механизм.step"})if(d.ShowLocalizedDialog(this)==DialogResult.OK){StepExport.Write(model,d.FileName);status.Text="STEP сохранён: "+d.FileName;}}catch(Exception e){UiMessage.Show(this,e.Message,"Экспорт");}}

  void ExportStl(){try{var model=ExportModel(true);using(var d=new SaveFileDialog{Filter="STL, миллиметры|*.stl",FileName="Деталь.stl"})if(d.ShowLocalizedDialog(this)==DialogResult.OK){using(var stream=File.Create(d.FileName))PrintExport.Stl(model.Parts[0],stream);status.Text="STL сохранён: "+d.FileName;}}catch(Exception e){UiMessage.Show(this,e.Message,"Экспорт");}}

  void ExportCsv(){if(!Solution.Valid){UiMessage.Show(this,"Исправьте связи перед экспортом расчёта.");return;}using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName="Расчёт_механизма.csv"})if(d.ShowLocalizedDialog(this)==DialogResult.OK){var text=new StringBuilder("Вал;Об/мин;Предельный момент одной ветви Нм;Нужный момент Нм;Мощность нагрузки Вт;Связан\r\n");foreach(var p in Project.Parts.Where(a=>a.Kind=="shaft")){var s=Solution.Shafts[p.Id];text.AppendLine("\""+p.Name.Replace("\"","\"\"")+"\";"+(s.Connected?Engine.F(s.Rpm):"")+";"+(s.Connected?Engine.F(s.AvailableTorque):"")+";"+(s.Connected?Engine.F(s.RequiredTorque):"")+";"+(s.Connected?Engine.F(s.LoadPower):"")+";"+s.Connected);}ReleaseSupport.WriteText(d.FileName,text.ToString(),new UTF8Encoding(true));}}

  void Help(){UiMessage.Show(this,"1. Создайте вал и задайте входные обороты / момент; нажмите «Задать вход».\n2. Выберите вал и добавьте шестерню: посадка выполняется автоматически. Справа можно сменить вал и положение по Z.\n3. Создайте второй вал с шестернёй и нажмите «Связать». Модули должны совпадать; ведомый вал можно расставить автоматически.\n4. Задайте сопротивляющий момент в параметрах выходного вала. Таблица покажет требуемый входной момент, обороты и силы. Без нагрузки передаваемое усилие равно нулю; предельный момент показан отдельно.\n5. Для CAD: размеры справа, ступени вала, отверстия/круглые карманы, либо эскиз XY → выдавливание по Z. Перетаскивание сохраняет положение.\n6. Проект сохраняется как .mechanism.json; геометрия экспортируется в STEP/STL.\n\nЭто параметрический конструктор передач с параллельными осями, не полный CAD Fusion. Для произвольных пространственных булевых операций и сложных поверхностей используйте STEP в CAD.\n\nCtrl+S — сохранить, Ctrl+O — открыть, Ctrl+Z/Y — отмена/повтор. Плотность влияет на массу; расчёт прочности и динамики не выполняется.","Конструктор механизмов",MessageBoxButtons.OK,MessageBoxIcon.Information);}

  void KeysPressed(object sender,KeyEventArgs e){if(e.Control&&e.KeyCode==Keys.S){Save(e.Shift);e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.O){Open();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Z){Undo();e.SuppressKeyPress=true;}else if(e.Control&&e.KeyCode==Keys.Y){Redo();e.SuppressKeyPress=true;}else if(e.KeyCode==Keys.Delete&&tree.Focused){DeletePart();e.SuppressKeyPress=true;}}

  void TogglePlay(){if(playing){Stop();return;}if(!play.Enabled||!Scene.Ready)return;moveButton.Checked=false;Scene.SetMoveMode(false);playing=true;lastTick=clock.Elapsed.TotalSeconds;timer.Start();play.Text="Ⅱ Пауза";Scene.SetMoveMode(false);}

  void Stop(){playing=false;timer.Stop();if(play!=null)play.Text="▶ Вращать";}

  void Tick(){double now=clock.Elapsed.TotalSeconds,dt=Math.Min(.1,now-lastTick);lastTick=now;if(!playing||!Scene.Ready)return;phase+=dt*Project.InputRpm*Math.PI/30*(double)timeScale.Value;Scene.UpdatePose(phase);}

  internal void ApproveTestClose(){closingApproved=true;}

  public void ConfigureForRobot(MechanismProject seed,Func<MechanismProject,string,bool> accept){if(seed!=null){Project=seed.Clone();savedSerialized=Project.Serialize();selectedId=Project.Parts.Where(p=>p.Kind=="shaft"&&p.Id!=Project.DriveShaftId).Select(p=>p.Id).LastOrDefault();Rebuild();}var bar=Controls.OfType<ToolStrip>().FirstOrDefault(t=>t.Name=="ProjectTools");if(bar!=null)Add(bar,"Использовать в роботе",()=>{var shaft=Project.Shaft(Selected);if(shaft==null||Solution==null||!Solution.Valid||!Solution.Shafts.ContainsKey(shaft.Id)||!Solution.Shafts[shaft.Id].Connected){UiMessage.Show(this,"Выберите связанный выходной вал в дереве.");return;}if(shaft.Id==Project.DriveShaftId){UiMessage.Show(this,"В качестве выхода выберите ведомый вал.");return;}if(accept(Project.Clone(),shaft.Id)){savedSerialized=Project.Serialize();closingApproved=true;Close();}});}

  protected override void Dispose(bool disposing){if(disposing&&!uiDisposed){uiDisposed=true;timer.Dispose();recovery.Dispose();Scene.Dispose();host.Child=null;}base.Dispose(disposing);}

 }

}



